package com.nigson.acceptance.inventory;
import com.nigson.commerce.inventory.*;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import java.util.*;
import java.time.*;
import java.net.*;
import java.net.http.*;
import static org.assertj.core.api.Assertions.*;
/** Actual staff endpoints, encrypted JDBC cookies, CSRF/current authority and safe wire errors. */
public final class InventoryHttpAcceptance {
 private InventoryHttpAcceptance(){}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base)throws Exception{
  if(System.getenv("NIGSON_TEST_INVENTORY")==null)return;var sessions=app.getBean(JdbcSessionTrust.class);var cookies=new ArrayList<String>();var csrf=new ArrayList<String>();
  try(var f=new InventoryFixture(app.getBean(JdbcTemplate.class),app.getBean(InventoryService.class),app.getBean(StockLedger.class),app.getBean(PlatformTransactionManager.class))){
   for(UUID party:List.of(f.operator,f.orders.party)){String issuer=f.jdbc.queryForObject("SELECT identity_issuer FROM commerce.party WHERE id=?",String.class,party);var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String token=JdbcSessionTrust.opaque();csrf.add(token);String session=sessions.authenticate(flow.sessionId(),new SessionRecord(1,party,issuer,party.toString(),Instant.now(),Instant.now(),"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),token,SessionRecord.TokenState.READY));cookies.add("__Host-nigson-session="+session);}
   String inventory=base+"/api/v1/staff/inventory",locations=base+"/api/v1/staff/stock-locations",adjustments=base+"/api/v1/staff/stock-adjustments";assertThat(send(http,HttpRequest.newBuilder(URI.create(inventory)).GET()).statusCode()).isEqualTo(401);assertThat(send(http,HttpRequest.newBuilder(URI.create(inventory)).header("Cookie",cookies.get(1)).GET()).statusCode()).isEqualTo(403);
   for(String query:List.of("?size=101","?page=-1","?page=0&page=1","?sort=privatePayload,asc","?owner="+f.operator))assertThat(send(http,HttpRequest.newBuilder(URI.create(inventory+query)).header("Cookie",cookies.getFirst()).GET()).statusCode()).isEqualTo(400);
   String code="SYNTH_"+UUID.randomUUID().toString().substring(0,8).toUpperCase(),locationBody=EventCodec.JSON.writeValueAsString(Map.of("code",code,"name","Synthetic HTTP offline location"));String locationKey=UUID.randomUUID().toString();assertThat(send(http,mutation(locations,cookies.getFirst(),"wrong",locationKey,locationBody)).statusCode()).isEqualTo(401);var created=send(http,mutation(locations,cookies.getFirst(),csrf.getFirst(),locationKey,locationBody));assertThat(created.statusCode()).isEqualTo(201);UUID location=UUID.fromString(EventCodec.JSON.readTree(created.body()).get("id").asString());f.locations.add(location);assertThat(send(http,mutation(locations,cookies.getFirst(),csrf.getFirst(),locationKey,locationBody)).body()).isEqualTo(created.body());assertThat(send(http,mutation(locations,cookies.getFirst(),csrf.getFirst(),"duplicate-code",locationBody)).statusCode()).isEqualTo(409);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_balance WHERE location_id=?",Integer.class,location)).isZero();
   UUID sku=f.sku(2);String body=EventCodec.JSON.writeValueAsString(Map.of("skuId",sku,"locationId",location,"delta","3.50","reason","Synthetic HTTP stock correction")),key=UUID.randomUUID().toString();assertThat(send(http,mutation(adjustments,cookies.getFirst(),csrf.getFirst(),key,body)).statusCode()).isEqualTo(400);var stock=send(http,mutation(adjustments,cookies.getFirst(),csrf.getFirst(),key,body).header("If-Match","\"0\""));assertThat(stock.statusCode()).isEqualTo(201);assertThat(stock.headers().firstValue("ETag")).hasValue("\"1\"");assertThat(stock.headers().firstValue("Cache-Control")).hasValue("no-store");assertThat(EventCodec.JSON.readTree(stock.body()).get("available").asString()).isEqualTo("3.50");assertThat(send(http,mutation(adjustments,cookies.getFirst(),csrf.getFirst(),key,body).header("If-Match","\"0\"")).body()).isEqualTo(stock.body());
   assertThat(send(http,mutation(adjustments,cookies.getFirst(),csrf.getFirst(),"stale",body).header("If-Match","\"0\"")).statusCode()).isEqualTo(412);assertThat(send(http,mutation(adjustments,cookies.getFirst(),csrf.getFirst(),key,body.replace("3.50","4.00")).header("If-Match","\"0\"")).statusCode()).isEqualTo(409);var shortage=send(http,mutation(adjustments,cookies.getFirst(),csrf.getFirst(),"negative",body.replace("3.50","-4.00")).header("If-Match","\"1\""));assertThat(shortage.statusCode()).isEqualTo(422);assertThat(shortage.body()).contains("INVENTORY_RULE_VIOLATION").doesNotContain("inventory_balance","Synthetic HTTP stock correction");
   var list=send(http,HttpRequest.newBuilder(URI.create(inventory+"?skuId="+sku+"&locationId="+location+"&sort=available,desc")).header("Cookie",cookies.getFirst()).GET());assertThat(list.statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(list.body()).get("items").size()).isEqualTo(1);assertThat(list.body()).doesNotContain("reason","created_by","movement");assertThat(app.getBean(io.micrometer.core.instrument.MeterRegistry.class).find("nigson.inventory.movements").tag("movement_type","ADJUST").counter().count()).isEqualTo(1);f.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=?",f.operator);assertThat(send(http,mutation(adjustments,cookies.getFirst(),csrf.getFirst(),key,body).header("If-Match","\"0\"")).statusCode()).isEqualTo(403);
  }finally{for(String cookie:cookies)sessions.logout(cookie.substring(cookie.indexOf('=')+1));}
 }
 static HttpRequest.Builder mutation(String uri,String cookie,String csrf,String key,String body){return HttpRequest.newBuilder(URI.create(uri)).header("Cookie",cookie).header("X-CSRF-TOKEN",csrf).header("Idempotency-Key",key).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body));}
 static HttpResponse<String> send(HttpClient http,HttpRequest.Builder request)throws Exception{return http.send(request.timeout(Duration.ofSeconds(10)).build(),HttpResponse.BodyHandlers.ofString());}
}
